import csv,json,collections,pathlib
from extract import WORK,ROOT

def tsv(n):
 with open(WORK/n) as f:return list(csv.DictReader(f,delimiter='\t'))
def yranges(s):
 vals=s.split(',');ints=sorted(int(x) for x in vals if x.isdigit());other=[x for x in vals if not x.isdigit()];out=[]
 if ints:
  start=last=ints[0]
  for x in ints[1:]:
   if x==last+1:last=x
   else:out.append(str(start) if start==last else f'{start}–{last}');start=last=x
  out.append(str(start) if start==last else f'{start}–{last}')
 return ', '.join(out+other)
def pct(a,b):return f'{int(a)/int(b):.1%}' if int(b) else '—'
s=json.loads((WORK/'summary.json').read_text());vol=tsv('volume_checks.tsv');ser=tsv('series_checks.tsv');worst=tsv('most_disagreement.tsv');eye=tsv('eye_review.tsv')
